import { describe, expect, it } from "vitest";
import { V4_META } from "../v4/data/v4Meta";

/**
 * The v4 migration cycle publishes an adaptiveness median only when every
 * reference-cohort program has been scored. These guard the contract the
 * report page relies on to decide whether a position label may be shown.
 *
 * `V4_META` is generated by `npm --prefix scripts run dfva:gen-v4`; these tests
 * assert the invariants of that generation, so a partially-scored cohort can
 * never silently publish a median.
 */
describe("V4_META migration-cycle contract", () => {
  it("publishes a median only when the cohort is complete", () => {
    if (V4_META.complete) {
      expect(V4_META.adaptMedian).not.toBeNull();
    } else {
      // A median over a partial cohort is a different statistic from the one a
      // reader would take it for, so it must be withheld entirely.
      expect(V4_META.adaptMedian).toBeNull();
    }
  });

  it("reports completeness consistently with the scored count", () => {
    expect(V4_META.complete).toBe(V4_META.scored === V4_META.cohortSize);
    expect(V4_META.pending).toHaveLength(V4_META.cohortSize - V4_META.scored);
  });

  it("inherits the exposure median unchanged — v4 does not touch Panel A", () => {
    expect(V4_META.expMedian).toBe(90.9);
  });

  it("scopes the cohort to the reference programs, not the placed portfolio", () => {
    // v3.1 §10a rule 2: extension programs are placed against the reference
    // thresholds and never re-base them. 38 placed = 34 reference + 4 extension.
    expect(V4_META.cohortSize).toBe(34);
  });
});

/** The median rule the generator implements, restated here so the arithmetic
 *  is checked independently of the data currently on disk. */
function median(values: number[]): number {
  const v = [...values].sort((a, b) => a - b);
  return v.length % 2
    ? v[(v.length - 1) / 2]
    : (v[v.length / 2 - 1] + v[v.length / 2]) / 2;
}

describe("adaptiveness median arithmetic", () => {
  it("averages the middle pair on an even cohort", () => {
    // 34 is even, so the v4 median is the mean of the 17th and 18th values and
    // may land on a half point.
    const evenCohort = [...Array(17).fill(9), ...Array(17).fill(12)];
    expect(evenCohort).toHaveLength(34);
    expect(median(evenCohort)).toBe(10.5);
  });

  it("takes the middle value on an odd cohort", () => {
    expect(median([6, 9, 14])).toBe(9);
  });

  it("is order-independent", () => {
    expect(median([12, 6, 9, 14])).toBe(median([14, 9, 6, 12]));
  });

  it("a half-point median leaves no program tied at the threshold", () => {
    // The quadrant rule is `adaptiveness >= median`. Panel C scores are
    // integers, so a half-point median cannot be tied — which removes the
    // tie-sensitivity that put 9 of 34 v3.1 programs exactly on the threshold.
    const m = 10.5;
    const scores = [8, 9, 10, 11, 12];
    expect(scores.some((s) => s === m)).toBe(false);
    expect(scores.filter((s) => s >= m)).toEqual([11, 12]);
  });
});
